# generated by tools/ail2py.py from wav_audio_main.ail; edit the .ail until onelang s16
from wav_audio import *
from checked_integer import *
from file_identity import *
from ail import read_bytes, write_bytes
import sys

def main() -> int:
    if len(sys.argv) != 6:
        print('usage: wav_audio gain|trim INPUT OUTPUT A B', file=sys.stderr)
        return 2
    try:
        mode: str = sys.argv[1]
        if mode != 'gain' and mode != 'trim':
            raise ValueError
        input: str = sys.argv[2]
        output: str = sys.argv[3]
        a: int = parse_int64_decimal(sys.argv[4])
        b: int = parse_int64_decimal(sys.argv[5])
        if input == output or file_paths_same(input, output):
            raise ValueError
        data: bytes = read_bytes(input)
        result: bytes = b''
        if mode == 'gain':
            result = wav_audio_gain(data, a, b)
        else:
            result = wav_audio_trim(data, a, b)
        write_bytes(output, result)
        return 0
    except ValueError:
        print('invalid WAV, parameters, or output alias', file=sys.stderr)
        return 2
    except OSError:
        print('WAV file error', file=sys.stderr)
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
